# EVOLVE-BLOCK-START
"""
Prefix-cache-oriented dataframe column permutation.

The evaluator scores serialized row strings, so this implementation preserves all
source cells while selecting safe source-column permutations that improve
character-prefix sharing.

The bounded candidates are:
1. A global column order ranked by len(value) * count * (count - 1).
2. A conditional partition tree that chooses leading fields separately inside
   row groups with repeated values.
3. A row-specific shared-prefix-anchor proposal that may choose different legal
   leading blocks per row when equivalent serialized block values occur across
   different columns.

Candidates are compared using the exact ideal serial-Trie objective:
the sum of LCP lengths of lexicographically adjacent serialized rows.
"""

from typing import List, Tuple
import math

import numpy as np
import pandas as pd

from solver import Algorithm


class Evolved(Algorithm):
    """Choose bounded, data-preserving column permutations for prefix reuse."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe for Algorithm compatibility."""
        self.df = df

    @staticmethod
    def _serial_value(value) -> str:
        """Convert one source cell to evaluator-compatible serialization text."""
        if value is None or value is pd.NA:
            return ""

        if isinstance(value, float):
            try:
                if math.isnan(value):
                    return ""
            except Exception:
                pass

        try:
            missing = pd.isna(value)
            if isinstance(missing, (bool, np.bool_)) and missing:
                return ""
        except Exception:
            pass

        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Compute character LCP using logarithmic slice comparisons in C."""
        limit = min(len(left), len(right))
        if limit == 0:
            return 0
        if left == right:
            return limit

        low, high = 0, limit
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _trie_score(cls, strings: List[str]) -> int:
        """Return exact ideal Trie reuse from sorted adjacent-row LCP values."""
        if len(strings) < 2:
            return 0

        ordered = sorted(strings)
        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            total += cls._lcp(previous, current)
            previous = current
        return total

    @staticmethod
    def _serialize(cells, orders):
        """Serialize every row according to its source-column permutation."""
        return [
            "".join(cells[row_id][column_id] for column_id in order)
            for row_id, order in enumerate(orders)
        ]

    @staticmethod
    def _resolve_constraints(columns, col_merge, one_way_dep):
        """Build contiguous merge blocks and precedence edges from API constraints."""
        ncols = len(columns)
        parent = list(range(ncols))

        def find(node):
            while parent[node] != node:
                parent[node] = parent[parent[node]]
                node = parent[node]
            return node

        def union(left, right):
            left_root, right_root = find(left), find(right)
            if left_root != right_root:
                parent[right_root] = left_root

        def locate(name):
            exact = [i for i, column in enumerate(columns) if column == name]
            if len(exact) == 1:
                return exact[0]

            text = str(name)
            partial = [
                i for i, column in enumerate(columns)
                if text in str(column)
            ]
            return partial[0] if len(partial) == 1 else None

        for group in col_merge or []:
            positions = [locate(name) for name in group]
            positions = [position for position in positions if position is not None]
            for position in positions[1:]:
                union(positions[0], position)

        grouped = {}
        for column_id in range(ncols):
            grouped.setdefault(find(column_id), []).append(column_id)

        blocks = sorted(grouped.values(), key=lambda block: min(block))
        block_of = {}
        for block_id, block in enumerate(blocks):
            for column_id in block:
                block_of[column_id] = block_id

        edges = set()
        for dependency in one_way_dep or []:
            if not isinstance(dependency, (tuple, list)) or len(dependency) != 2:
                continue

            before = locate(dependency[0])
            after = locate(dependency[1])
            if before is not None and after is not None:
                source = block_of[before]
                target = block_of[after]
                if source != target:
                    edges.add((source, target))

        return blocks, sorted(edges)

    @staticmethod
    def _topological_blocks(blocks, edges, priority):
        """Return a deterministic priority-aware legal block ordering."""
        nblocks = len(blocks)
        children = [[] for _ in range(nblocks)]
        indegree = [0] * nblocks

        for source, target in edges:
            children[source].append(target)
            indegree[target] += 1

        def key(block_id):
            return (
                min(priority[column_id] for column_id in blocks[block_id]),
                min(blocks[block_id]),
            )

        available = [block_id for block_id in range(nblocks) if indegree[block_id] == 0]
        result = []

        while available:
            available.sort(key=key)
            current = available.pop(0)
            result.append(current)

            for target in children[current]:
                indegree[target] -= 1
                if indegree[target] == 0:
                    available.append(target)

        # Cyclic dependencies cannot all be topologically honored; retain a
        # deterministic stable completion rather than dropping any block.
        if len(result) < nblocks:
            used = set(result)
            remaining = [block_id for block_id in range(nblocks) if block_id not in used]
            remaining.sort(key=key)
            result.extend(remaining)

        return result

    @staticmethod
    def _flatten(block_order, blocks):
        """Expand an ordered block list into a source-column permutation."""
        return [
            column_id
            for block_id in block_order
            for column_id in blocks[block_id]
        ]

    @staticmethod
    def _factorize(cells, nrows, ncols):
        """Factorize each serialized source column once for group statistics."""
        codes = []
        lengths = []

        for column_id in range(ncols):
            mapping = {}
            column_codes = np.empty(nrows, dtype=np.int32)
            value_lengths = []

            for row_id in range(nrows):
                value = cells[row_id][column_id]
                code = mapping.get(value)
                if code is None:
                    code = len(mapping)
                    mapping[value] = code
                    value_lengths.append(len(value))
                column_codes[row_id] = code

            codes.append(column_codes)
            lengths.append(np.asarray(value_lengths, dtype=np.int64))

        return codes, lengths

    @staticmethod
    def _group_weight(row_ids, column_codes, value_lengths):
        """Measure length-weighted repeated-value pair mass inside one row group."""
        if len(row_ids) < 2:
            return 0

        counts = np.bincount(
            column_codes[row_ids],
            minlength=len(value_lengths),
        )
        return int(np.dot(value_lengths, counts * (counts - 1)))

    def _conditional_orders(
        self,
        blocks,
        edges,
        base_block_order,
        candidate_blocks,
        codes,
        lengths,
        nrows,
    ):
        """Build a bounded conditional repeated-prefix partition tree."""
        nblocks = len(blocks)
        predecessors = [set() for _ in range(nblocks)]
        for source, target in edges:
            predecessors[target].add(source)

        output = [None] * nrows
        max_depth = min(7, nblocks)
        max_nodes = 112
        node_count = 0

        def finish(prefix, remaining):
            tail = [block for block in base_block_order if block in remaining]
            return self._flatten(prefix + tail, blocks)

        def assign(row_ids, order):
            for row_id in row_ids:
                output[int(row_id)] = order

        def visit(row_ids, prefix, remaining, depth):
            nonlocal node_count

            if (
                len(row_ids) < 2
                or not remaining
                or depth >= max_depth
                or node_count >= max_nodes
            ):
                assign(row_ids, finish(prefix, remaining))
                return

            available = [
                block for block in remaining
